<?php
require_once __DIR__ . '/../../config/response.php'; require_once __DIR__ . '/../../config/security.php';
header('Cache-Control: no-store'); if($_SERVER['REQUEST_METHOD']!=='POST') jsonResponse(['success'=>false,'error'=>'Method not allowed.'],405); $pdo=Database::getInstance(); $input=getJsonInput(); $session=validateSession($pdo,getBearerToken()?:($input['token']??''),15); if(!$session['valid']||!empty($session['is_2fa_pending'])) jsonResponse(['success'=>false,'error'=>'Please sign in to continue.'],401); $uid=(int)$session['user']['id']; $code=strtoupper(trim((string)($input['currency']??''))); if(!preg_match('/^[A-Z0-9]{2,12}$/',$code)) jsonResponse(['success'=>false,'error'=>'Invalid currency.'],422); $stmt=$pdo->prepare('SELECT code,name,kind FROM currencies WHERE code=? AND is_enabled=1 LIMIT 1'); $stmt->execute([$code]); $currency=$stmt->fetch(); if(!$currency) jsonResponse(['success'=>false,'error'=>'That currency is not currently enabled.'],422); $existing=$pdo->prepare("SELECT uuid,status FROM wallets WHERE user_id=? AND currency_code=? AND wallet_type='personal' AND status<>'closed' LIMIT 1"); $existing->execute([$uid,$code]); if($row=$existing->fetch()) jsonResponse(['success'=>true,'already_active'=>true,'wallet'=>$row]); $uuid=generateUUID(); $insert=$pdo->prepare("INSERT INTO wallets(uuid,user_id,currency_code,wallet_type,status) VALUES(?,?,?,?, 'active')"); $insert->execute([$uuid,$uid,$code,'personal']); jsonResponse(['success'=>true,'already_active'=>false,'wallet'=>['uuid'=>$uuid,'currency_code'=>$code,'name'=>$currency['name'],'kind'=>$currency['kind'],'status'=>'active']]);
